-- ==========================================
-- SCRIPT DE CRIAÇÃO DO BANCO DE DADOS SUPABASE
-- Sistema Associação Boas Novas
-- Copie e cole este código no SQL Editor do Supabase e clique em 'RUN'
-- ==========================================

-- 1. TABELA DE SÓCIOS
CREATE TABLE IF NOT EXISTS public.socios (
    id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    codigo BIGINT UNIQUE,
    nome TEXT NOT NULL,
    cpf TEXT,
    rg TEXT,
    telefones TEXT,
    celular TEXT,
    n_dia INTEGER,
    n_mes INTEGER,
    n_ano INTEGER,
    data_nascimento TEXT,
    naturalidade TEXT,
    estado_civil TEXT,
    data_cadastro TEXT,
    tipo_sanguineo TEXT,
    categoria TEXT,
    sexo TEXT,
    situacao TEXT DEFAULT 'ATIVO',
    agente_cadastrador TEXT,
    data_cancelamento TEXT,
    estado TEXT,
    email TEXT,
    foto_url TEXT,
    obs TEXT,
    tipo_endereco TEXT DEFAULT 'RESIDENCIAL',
    logradouro TEXT,
    numero TEXT,
    complemento TEXT,
    bairro TEXT,
    cidade TEXT,
    cep TEXT,
    telefone_fixo TEXT,
    dependentes JSONB DEFAULT '[]'::jsonb,
    documentos JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

ALTER TABLE public.socios ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Acesso total socios" ON public.socios;
CREATE POLICY "Acesso total socios" ON public.socios FOR ALL USING (true) WITH CHECK (true);

-- 2. TABELA DE FATURAS / FINANCEIRO
CREATE TABLE IF NOT EXISTS public.faturas (
    num_ordem BIGINT PRIMARY KEY,
    num_fatura BIGINT,
    duplicata INTEGER,
    valor_duplicata NUMERIC(12, 2) DEFAULT 0,
    dt_vencimento TEXT,
    dt_pago TEXT,
    descontos NUMERIC(12, 2) DEFAULT 0,
    status TEXT DEFAULT 'Pendente',
    socio_codigo BIGINT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

ALTER TABLE public.faturas ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Acesso total faturas" ON public.faturas;
CREATE POLICY "Acesso total faturas" ON public.faturas FOR ALL USING (true) WITH CHECK (true);

-- 3. TABELA DE PROFISSIONAIS
CREATE TABLE IF NOT EXISTS public.profissionais (
    id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    nome TEXT NOT NULL,
    especialidade TEXT NOT NULL,
    telefone TEXT,
    status TEXT DEFAULT 'Ativo',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

ALTER TABLE public.profissionais ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Acesso total profissionais" ON public.profissionais;
CREATE POLICY "Acesso total profissionais" ON public.profissionais FOR ALL USING (true) WITH CHECK (true);

-- 4. TABELA DE CONSULTAS / AGENDA
CREATE TABLE IF NOT EXISTS public.consultas (
    id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    data TEXT NOT NULL,
    hora TEXT NOT NULL,
    paciente TEXT NOT NULL,
    profissional TEXT NOT NULL,
    modalidade TEXT NOT NULL,
    convenio TEXT DEFAULT 'Particular',
    carteirinha TEXT,
    valor NUMERIC(12, 2) DEFAULT 0,
    status TEXT DEFAULT 'Agendado',
    observacoes TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

ALTER TABLE public.consultas ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Acesso total consultas" ON public.consultas;
CREATE POLICY "Acesso total consultas" ON public.consultas FOR ALL USING (true) WITH CHECK (true);

-- 5. TABELA DE CURSOS
CREATE TABLE IF NOT EXISTS public.cursos (
    id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
    nome TEXT NOT NULL,
    categoria TEXT,
    professor TEXT,
    horario TEXT,
    inscritos INTEGER DEFAULT 0,
    vagas INTEGER DEFAULT 30,
    status TEXT DEFAULT 'Ativo',
    cor TEXT DEFAULT '#3b82f6',
    turmas JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

ALTER TABLE public.cursos ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Acesso total cursos" ON public.cursos;
CREATE POLICY "Acesso total cursos" ON public.cursos FOR ALL USING (true) WITH CHECK (true);

